import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"45、【萃】 坤下兌上","description":"溫公易說 - 45、【萃】 坤下兌上","frontmatter":{"title":"45、【萃】 坤下兌上","description":"溫公易說 - 45、【萃】 坤下兌上"},"headers":[],"relativePath":"classics/wengong/046.md","filePath":"classics/wengong/046.md"}'),l={name:"classics/wengong/046.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_45、【萃】-坤下兌上" tabindex="-1">45、【萃】 坤下兌上 <a class="header-anchor" href="#_45、【萃】-坤下兌上" aria-label="Permalink to “45、【萃】 坤下兌上”">​</a></h1><h3 id="彖曰-萃-聚也。順以說-剛中而應-故聚也。王假有廟-致孝亨也。利見大人-亨聚以正也。用大牲-吉利有攸往-順天命也。觀其所聚-而天地萬物之情可見矣。" tabindex="-1">彖曰：萃，聚也。順以說，剛中而應，故聚也。王假有廟，致孝亨也。利見大人，亨聚以正也。用大牲，吉利有攸往，順天命也。觀其所聚，而天地萬物之情可見矣。 <a class="header-anchor" href="#彖曰-萃-聚也。順以說-剛中而應-故聚也。王假有廟-致孝亨也。利見大人-亨聚以正也。用大牲-吉利有攸往-順天命也。觀其所聚-而天地萬物之情可見矣。" aria-label="Permalink to “彖曰：萃，聚也。順以說，剛中而應，故聚也。王假有廟，致孝亨也。利見大人，亨聚以正也。用大牲，吉利有攸往，順天命也。觀其所聚，而天地萬物之情可見矣。”">​</a></h3><p>物順以說，萃之象也。上剛中而下應之，亦聚之象也。大人者，以正聚物者也。聚得大人，然後通也。</p><h3 id="象曰-澤上於地-萃。君子以除戎器-戒不虞。" tabindex="-1">象曰：澤上於地，萃。君子以除戎器，戒不虞。 <a class="header-anchor" href="#象曰-澤上於地-萃。君子以除戎器-戒不虞。" aria-label="Permalink to “象曰：澤上於地，萃。君子以除戎器，戒不虞。”">​</a></h3><h3 id="初六-有孚不終-乃亂乃萃。若號-一握為笑-勿恤-往無咎-象曰-乃亂乃萃-其志亂也。" tabindex="-1">初六：有孚不終，乃亂乃萃。若號，一握為笑，勿恤，往無咎 象曰：乃亂乃萃，其志亂也。 <a class="header-anchor" href="#初六-有孚不終-乃亂乃萃。若號-一握為笑-勿恤-往無咎-象曰-乃亂乃萃-其志亂也。" aria-label="Permalink to “初六：有孚不終，乃亂乃萃。若號，一握為笑，勿恤，往無咎 象曰：乃亂乃萃，其志亂也。”">​</a></h3><h3 id="六二-引吉-無咎。孚乃利用禴-象曰-引吉無咎-中未變也。" tabindex="-1">六二：引吉，無咎。孚乃利用禴 象曰：引吉無咎，中未變也。 <a class="header-anchor" href="#六二-引吉-無咎。孚乃利用禴-象曰-引吉無咎-中未變也。" aria-label="Permalink to “六二：引吉，無咎。孚乃利用禴 象曰：引吉無咎，中未變也。”">​</a></h3><h3 id="六三-萃如-嗟如-無攸利。往無咎-小吝-象曰-往無咎-上巽也。" tabindex="-1">六三：萃如，嗟如，無攸利。往無咎，小吝 象曰：往無咎，上巽也。 <a class="header-anchor" href="#六三-萃如-嗟如-無攸利。往無咎-小吝-象曰-往無咎-上巽也。" aria-label="Permalink to “六三：萃如，嗟如，無攸利。往無咎，小吝 象曰：往無咎，上巽也。”">​</a></h3><h3 id="九四-大吉無咎-象曰-大吉無咎-位不當也。" tabindex="-1">九四：大吉無咎 象曰：大吉無咎，位不當也。 <a class="header-anchor" href="#九四-大吉無咎-象曰-大吉無咎-位不當也。" aria-label="Permalink to “九四：大吉無咎 象曰：大吉無咎，位不當也。”">​</a></h3><h3 id="九五-萃有位-無咎。匪孚-元永貞-悔亡-象曰-萃有位-志未光也。" tabindex="-1">九五：萃有位，無咎。匪孚，元永貞，悔亡 象曰：萃有位，志未光也。 <a class="header-anchor" href="#九五-萃有位-無咎。匪孚-元永貞-悔亡-象曰-萃有位-志未光也。" aria-label="Permalink to “九五：萃有位，無咎。匪孚，元永貞，悔亡 象曰：萃有位，志未光也。”">​</a></h3><p>以剛中之德，僅能保位無咎，而德信不洽於民，未足光也。故必以元永貞之道聚民，然後悔亡也。</p><h3 id="上六-齎諮涕洟-無咎-象曰-齎諮涕洟-未安上也。" tabindex="-1">上六：齎諮涕洟，無咎 象曰：齎諮涕洟，未安上也。 <a class="header-anchor" href="#上六-齎諮涕洟-無咎-象曰-齎諮涕洟-未安上也。" aria-label="Permalink to “上六：齎諮涕洟，無咎 象曰：齎諮涕洟，未安上也。”">​</a></h3>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
